flowchart TD
  start["Início: Análise do Vocábulo 'Que'"] --> dec_anterior{"Termo imediatamente anterior\né substantivo ou pronome?\n(Varredura Prévia)}
  dec_anterior -- "Não (verbo, advérbio, preposição)" --> res_descarte["Hipótese de Relativo Descartada\n(Conjunção integrante, expletiva ou preposição)"]
  dec_anterior -- "Sim (substantivo ou termo afim)" --> dec_retomada{"O 'que' resgata semanticamente\nesse termo na oração seguinte?}
  dec_retomada -- "Não" --> res_descarte
  dec_retomada -- "Sim" --> dec_substituicao{"Teste Canônico: Admite troca por\n'o qual / a qual / os quais / as quais'?}
  dec_substituicao -- "Sim" --> res_confirmado["Pronome Relativo Confirmado\n(Inicia Oração Subordinada Adjetiva)"]
  dec_substituicao -- "Não" --> res_descarte

flowchart TD
  start["Início: Mapear substantivos antecedentes e pronome relativo"] --> proc_read["Ler a oração subordinada adjetiva posterior"]
  proc_read --> dec_conc{"A concordância de número/gênero elimina candidatos?"}
  dec_conc -- "Sim" --> dec_restou{"Restou apenas um candidato compatível?"}
  dec_conc -- "Não" --> dec_semant{"Pela ação do verbo posterior, quem pratica ou sofre a ação?"}
  dec_restou -- "Sim" --> proc_encaixe["Encaixar o candidato eleito no lugar do pronome"]
  dec_restou -- "Não" --> dec_semant
  dec_semant -- "Apenas um candidato" --> proc_encaixe
  dec_semant -- "Mais de um candidato" --> res_ambig["Ambiguidade textual viciosa: reescrever ou usar 'o qual / a qual'"]
  proc_encaixe --> dec_valida{"O encaixe mantém coerência e plenitude semântica?"}
  dec_valida -- "Sim" --> res_ok["Antecedente confirmado e oração validada"]
  dec_valida -- "Não" --> res_invalido["Incoerência semântica: reexaminar candidatos nominais"]

